const tabId = 1148881640;

// Let's test the groupedsearch API with various queries
async function search(q) {
  const res = await tool.fetch_url({
    url: `https://www.stubhub.com/search/groupedsearch?q=${encodeURIComponent(q)}&page=1&rows=20`,
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ text: q })
  });
  try {
    return JSON.parse(res.body);
  } catch (e) {
    return res.body;
  }
}

const queries = [
  "BTS", "BTS New York", "BTS MetLife", "BTS NJ", "BTS New Jersey",
  "Bangtan", "Jungkook", "Agust D", "Suga", "J-Hope", "Jimin", "RM", "Jin"
];

const results = {};
for (const q of queries) {
  const data = await search(q);
  results[q] = data?.resultsWithMetadata?.map(r => ({
    name: r.name,
    category: r.category,
    url: r.url,
    eventCount: r.eventCount
  })) || data;
}

console.log("Search results:", JSON.stringify(results, null, 2));

