}

const allEvents = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('a[href*="/event/"]')).map(a => {
    return {
      text: a.innerText.replace(/\n+/g, ' | '),
      href: a.href
    };
  });
  return cards;
});

