  const t = e.text.toLowerCase();
  return t.includes('new york') || t.includes('ny') || t.includes('nj') || t.includes('new jersey') || t.includes('metlife') || t.includes('prudential') || t.includes('barclays') || t.includes('madison');
});
console.log("NY/NJ events found:", JSON.stringify(nyEvents, null, 2));

// Also let's print all unique locations/cities
const cities = [...new Set(allEvents.map(e => {
  const parts = e.text.split('|');
  return parts.slice(3).join('|');
}))];
console.log("All event locations/descriptions:", cities);

