const tabId = 1148881640;

// Navigate to BTS performer page with all events
await tool.navigate({
  tabId,
  url: "https://www.stubhub.com/bts-tickets/performer/1503185?ct=ALL&tour=ALL"
});

await tool.wait_for({
  tabId,
  condition: "load_state",
  value: "load"
});

// Let's click "See 42 events in all locations" if it's there
await browserjs(tabId, () => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes('See 42 events') || b.innerText.includes('all locations'));
  if (btn) btn.click();
});

await new Promise(r => setTimeout(r, 1000));

// Extract all event cards / links
const eventsList = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('a[href*="/event/"]')).map(a => {
    return {
      text: a.innerText.replace(/\n+/g, ' | '),
      href: a.href
    };
  });
  return items;
});

console.log("Total events found:", eventsList.length);
console.log("Events:", JSON.stringify(eventsList, null, 2));

